def transform(grid):
    h, w = len(grid), len(grid[0])

    # Candidate parallel-line families: rows, columns, and both diagonals.
    key_funcs = [
        lambda r, c: r,
        lambda r, c: c,
        lambda r, c: c - r,
        lambda r, c: r + c,
    ]

    best_groups = None
    best_score = -1
    best_key = None

    for key_func in key_funcs:
        groups = {}
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color:
                    groups.setdefault(key_func(r, c), []).append(color)

        score = sum(len(colors) ** 2 for colors in groups.values())
        if score > best_score:
            best_score = score
            best_groups = groups
            best_key = key_func

    period = len(best_groups)
    pattern = {}
    for key, colors in best_groups.items():
        residue = key % period
        counts = {}
        for color in colors:
            counts[color] = counts.get(color, 0) + 1
        pattern[residue] = max(counts, key=counts.get)

    return [
        [pattern[best_key(r, c) % period] for c in range(w)]
        for r in range(h)
    ]
